#include "mka/movie_host_clock.hpp"
#include <cstdio>
#include <stdexcept>
#include <thread>
using namespace mka::video;
namespace {void check(bool v,const char* t){if(!v)throw std::runtime_error(t);}}
int main(){try{
    auto id=std::make_shared<const MovieSourceObservationIdentity>();MovieHostClockFailure f;std::int64_t ticks=100;bool broken=false;
    auto clock=NativeMovieHostClock::create_with_reader("fixture.sfd",id,3,[&]()->std::optional<std::int64_t>{if(broken)return {};return ticks;},f);check(bool(clock),"explicit deterministic clock");
    check(!clock->read("fixture.sfd",id,f)&&f.kind==MovieHostClockError::invalid_state,"read before begin cannot invent zero");
    check(clock->begin("fixture.sfd",id,f),"begin captures actual tick");ticks=101;auto one=clock->read("fixture.sfd",id,f);check(one&&one->elapsed==MovieClockRational{1,3},"exact first fractional interval");ticks=102;auto two=clock->read("fixture.sfd",id,f);check(two&&two->elapsed==MovieClockRational{2,3},"queries do not accumulate truncation drift");ticks=103;check(clock->pause("fixture.sfd",id,f),"pause captures interval");ticks=1000;auto paused=clock->read("fixture.sfd",id,f);check(paused&&paused->elapsed==MovieClockRational{1,1}&&paused->state==MovieHostClockState::paused,"paused wall interval excluded");check(clock->pause("fixture.sfd",id,f)&&clock->resume("fixture.sfd",id,f),"pause idempotent and resume recaptures");ticks=1001;check(clock->read("fixture.sfd",id,f)->elapsed==MovieClockRational{4,3},"interval ticks accumulated before division");ticks=1002;check(clock->stop("fixture.sfd",id,f),"stop captures active interval");ticks=9000;auto stopped=clock->read("fixture.sfd",id,f);check(stopped&&stopped->elapsed==MovieClockRational{5,3}&&stopped->state==MovieHostClockState::stopped&&clock->stop("fixture.sfd",id,f),"stopped value stable and stop idempotent");
    check(!clock->resume("fixture.sfd",id,f)&&f.kind==MovieHostClockError::invalid_state,"stopped epoch cannot resume");check(!clock->read("other",id,f)&&f.kind==MovieHostClockError::foreign_source,"key binding");check(!clock->read("fixture.sfd",std::make_shared<const MovieSourceObservationIdentity>(),f)&&f.kind==MovieHostClockError::foreign_source,"actual epoch binding");
    MovieHostClockFailure foreign;std::thread thread([&]{clock->read("fixture.sfd",id,foreign);});thread.join();check(foreign.kind==MovieHostClockError::wrong_thread,"owner thread guard");clock.reset();check(stopped->identity==id&&stopped->source_key=="fixture.sfd"&&stopped->elapsed==MovieClockRational{5,3},"owned reading after destruction");
    ticks=10;auto faulty=NativeMovieHostClock::create_with_reader("fixture.sfd",id,1,[&]()->std::optional<std::int64_t>{if(broken)return {};return ticks;},f);check(faulty->begin("fixture.sfd",id,f),"failure fixture begin");broken=true;check(!faulty->pause("fixture.sfd",id,f)&&f.kind==MovieHostClockError::query,"query failure named atomic");broken=false;ticks=9;check(!faulty->stop("fixture.sfd",id,f)&&f.kind==MovieHostClockError::regression,"regression named atomic");ticks=12;auto after=faulty->read("fixture.sfd",id,f);check(after&&after->state==MovieHostClockState::running&&after->elapsed==MovieClockRational{2,1},"failed transitions preserve actual running anchor");
    std::int64_t extreme=INT64_MIN;auto wide=NativeMovieHostClock::create_with_reader("wide",id,1,[&]{return std::optional<std::int64_t>{extreme};},f);check(wide->begin("wide",id,f),"signed tick boundary begin");extreme=INT64_MAX;check(!wide->read("wide",id,f)&&f.kind==MovieHostClockError::overflow,"unrepresentable native rational named");check(!wide->pause("wide",id,f)&&f.kind==MovieHostClockError::overflow,"pause overflow transactional");extreme=INT64_MIN+1;check(wide->read("wide",id,f)->elapsed==MovieClockRational{1,1},"failed query does not advance last tick");
    extreme=INT64_MIN;auto reduced=NativeMovieHostClock::create_with_reader("reduce",id,3,[&]{return std::optional<std::int64_t>{extreme};},f);check(reduced->begin("reduce",id,f),"wide reduced begin");extreme=INT64_MAX;auto large=reduced->read("reduce",id,f);check(large&&large->elapsed==MovieClockRational{6148914691236517205LL,1},"wide difference reduced before int64 result bounds");
    NativeMovieHostClock* raw=nullptr;bool reentry=false;auto guarded=NativeMovieHostClock::create_with_reader("guard",id,1,[&]{if(raw){MovieHostClockFailure nested;reentry=!raw->pause("guard",id,nested)&&nested.kind==MovieHostClockError::reentry;}return std::optional<std::int64_t>{1};},f);raw=guarded.get();check(guarded->begin("guard",id,f)&&reentry,"reader cannot reenter owner");
    check(!NativeMovieHostClock::create_with_reader("x",id,0,[]{return std::optional<std::int64_t>{0};},f)&&f.kind==MovieHostClockError::invalid_frequency,"frequency positive");
#ifdef _WIN32
    auto actual=NativeMovieHostClock::create("qpc",id,f);check(actual&&actual->begin("qpc",id,f),"actual Windows QPF/QPC begin");auto a=actual->read("qpc",id,f),b=actual->read("qpc",id,f);check(a&&b&&a->elapsed.denominator>0&&b->elapsed.denominator>0&&__int128(b->elapsed.numerator)*a->elapsed.denominator>=__int128(a->elapsed.numerator)*b->elapsed.denominator,"tiny actual QPC monotonic check without sleep");check(actual->stop("qpc",id,f),"actual QPC stop");
#endif
    check(std::puts("PASS native host elapsed clock exact intervals/source lifecycle; no master-clock policy binding")>=0&&std::fflush(stdout)==0,"checked output");return 0;
}catch(const std::exception& e){std::fprintf(stderr,"FAIL host clock %s\n",e.what());return 1;}}
